export const productDetails = {
  '02-picus': { headline: 'Kiểm chứng khả năng phòng thủ bằng mô phỏng có kiểm soát', summary: 'Picus Security Validation Platform mô phỏng hành vi tấn công để kiểm tra các lớp phòng thủ, tìm khoảng trống phát hiện và giúp đội ngũ ưu tiên khắc phục theo mức độ rủi ro.', intro: ['Tài liệu Picus trong thư viện tập trung vào hai hướng: Breach and Attack Simulation (BAS) và Continuous Threat Exposure Management (CTEM). Thay vì chỉ xem danh sách lỗ hổng, đội ngũ có thể kiểm chứng hệ thống bảo vệ phản ứng ra sao trước các kỹ thuật tấn công mô phỏng.', 'Quy trình CTEM được mô tả theo các bước xác định phạm vi, phát hiện tài sản và mức độ phơi nhiễm, ưu tiên rủi ro, xác thực khả năng khai thác, rồi thúc đẩy khắc phục và kiểm tra lại.'], capabilities: [{title:'Mô phỏng và xác thực kiểm soát',text:'Chạy các hành vi tấn công mô phỏng trong phạm vi được phê duyệt để đánh giá khả năng ngăn chặn và phát hiện của công cụ bảo mật.'},{title:'Ưu tiên rủi ro theo bối cảnh',text:'Kết hợp thông tin tài sản, phát hiện và khả năng khai thác để giúp đội ngũ chọn việc cần xử lý trước.'},{title:'Kiểm tra đường tấn công và quy tắc',text:'Tài liệu đề cập Attack Path Validation và Detection Rule Validation nhằm rà soát tuyến tấn công tiềm năng, cũng như chất lượng quy tắc giám sát.'},{title:'Theo dõi khắc phục',text:'Sau khi điều chỉnh biện pháp bảo vệ, có thể xác thực lại để xem khoảng trống đã được thu hẹp hay chưa.'}], useCases:['Rà soát định kỳ hiệu quả của EDR, SIEM và các lớp kiểm soát hiện có.','Chuẩn bị bằng chứng cho hoạt động đánh giá năng lực phòng thủ hoặc chương trình CTEM.','Xác định thứ tự xử lý khi có nhiều cảnh báo và điểm yếu cần xem xét.'], questions:[['Phạm vi mô phỏng','Những mạng, máy chủ, endpoint và thời điểm nào được phép đưa vào kịch bản?'],['An toàn vận hành','Kịch bản nào phù hợp để chạy trong môi trường production, kịch bản nào cần lab?'],['Tích hợp','Cần nhận dữ liệu hoặc đẩy kết quả sang SIEM, EDR, ticketing hay nguồn nào?'],['Đo kết quả','Nhóm sẽ dùng tiêu chí nào để so sánh trước và sau khi khắc phục?']], partners:['Picus Security'] },
  '03-niagara': { headline: 'Tạo đường quan sát tin cậy cho lưu lượng mạng', summary: 'Niagara Networks cung cấp các thành phần thu nhận, điều phối và phân phối lưu lượng để công cụ giám sát có được dữ liệu cần thiết từ mạng vật lý, ảo hóa hoặc cloud.', intro: ['Tài liệu kỹ thuật Niagara mô tả một hệ sinh thái Open Visibility dành cho SOC/NOC. Trọng tâm là đưa lưu lượng đến đúng công cụ phân tích mà không làm gián đoạn luồng dữ liệu đang vận hành.', 'Phạm vi tài liệu gồm Network TAP, Bypass Switch, Network Packet Broker, giải pháp cho môi trường ảo hóa và cloud, cùng khả năng điều phối visibility. Thiết kế cụ thể phụ thuộc sơ đồ mạng, tốc độ cổng và các công cụ nhận lưu lượng.'], capabilities:[{title:'Thu nhận lưu lượng',text:'Network TAP tạo điểm lấy lưu lượng phù hợp để đưa bản sao dữ liệu tới công cụ giám sát.'},{title:'Điều phối và lọc gói tin',text:'Packet Broker tập trung luồng từ nhiều điểm, áp dụng chính sách phân phối để sử dụng hiệu quả cổng nhận của công cụ.'},{title:'Duy trì đường truyền',text:'Bypass Switch hỗ trợ thiết kế đường đi qua thiết bị inline và phương án duy trì kết nối khi thiết bị kiểm tra gặp sự cố.'},{title:'Mở rộng sang môi trường ảo',text:'Tài liệu đề cập visibility cho hạ tầng ảo hóa và cloud; cần xác định nền tảng, vị trí triển khai và yêu cầu hiệu năng trước khi chọn cấu hình.'}],useCases:['Cấp dữ liệu mạng cho NDR, IDS/IPS, SIEM hoặc công cụ phân tích gói tin.','Hợp nhất nhiều điểm giám sát trong mạng doanh nghiệp hoặc trung tâm dữ liệu.','Rà soát lưu lượng mã hóa và nhu cầu giải mã theo chính sách của tổ chức.'],questions:[['Sơ đồ lấy lưu lượng','Cần quan sát những liên kết, VLAN, vùng mạng và luồng nào?'],['Năng lực cổng','Tốc độ, loại cổng và lưu lượng đỉnh đã được đo hoặc xác nhận chưa?'],['Tính liên tục','Thiết bị được đặt inline hay out-of-band, và yêu cầu fail-open/fail-close là gì?'],['Công cụ nhận dữ liệu','Các công cụ giám sát cần định dạng, lọc hoặc phân phối luồng ra sao?']],partners:['Niagara Networks'] },
  '04-apposite': { headline: 'Thử ứng dụng trong điều kiện mạng có thể kiểm soát', summary: 'Apposite Netropy giúp tạo lưu lượng kiểm thử và mô phỏng các đặc tính đường truyền để đội ngũ đánh giá hiệu năng ứng dụng, thiết bị hoặc hệ thống trước khi triển khai rộng.', intro:['Bộ tài liệu Apposite giới thiệu hai nhóm năng lực: sinh lưu lượng để đo khả năng xử lý của hệ thống, và giả lập mạng để tạo ra các điều kiện gần với thực tế như độ trễ, jitter, băng thông giới hạn hoặc mất gói.', 'Các bài kiểm thử có thể lặp lại với cùng cấu hình, nhờ đó nhóm kỹ thuật so sánh được kết quả giữa các phiên bản hoặc phương án triển khai. Thiết bị phần cứng hay bản ảo hóa cần được chọn theo mô hình lab và thông lượng mong muốn.'],capabilities:[{title:'Sinh lưu lượng kiểm thử',text:'Tạo luồng dữ liệu đi qua thiết bị hoặc ứng dụng để đo thông lượng, độ trễ và các chỉ số hiệu năng liên quan.'},{title:'Mô phỏng đường truyền',text:'Điều chỉnh băng thông, độ trễ, jitter và tỉ lệ mất gói để kiểm tra hành vi của ứng dụng trong các điều kiện mạng khác nhau.'},{title:'Lặp lại kịch bản',text:'Lưu cấu hình kiểm thử giúp nhóm tái tạo điều kiện thử nghiệm và đối chiếu kết quả giữa các lần chạy.'},{title:'Xuất và phân tích kết quả',text:'Tài liệu hướng dẫn đề cập báo cáo chỉ số và dữ liệu kiểm thử để phục vụ phân tích sau phiên chạy.'}],useCases:['Kiểm tra thiết bị mạng, firewall, VPN hoặc hệ thống mới trước khi đưa vào khai thác.','Đánh giá chất lượng thoại, video và ứng dụng phân tán khi đường truyền suy giảm.','Tái tạo sự cố mạng trong lab để tìm ngưỡng chịu tải hoặc điểm nghẽn.'],questions:[['Mục tiêu phép thử','Cần đo thông lượng, số phiên, độ trễ hay hành vi ứng dụng cụ thể nào?'],['Điều kiện mô phỏng','Các profile mạng được lấy từ số liệu vận hành hay kịch bản tham chiếu?'],['Tải và cổng kết nối','Năng lực phần cứng, tốc độ giao tiếp và quy mô đồng thời cần đáp ứng là bao nhiêu?'],['Tiêu chí đạt','Ngưỡng nghiệm thu và định dạng báo cáo mong muốn đã thống nhất chưa?']],partners:['Apposite Technologies'] },
  '05-crimewall-maltego': { headline: 'Lần theo mối liên hệ giữa dữ liệu và thực thể', summary: 'Maltego hỗ trợ thu thập dữ liệu từ các nguồn được cấp phép, biến kết quả thành đồ thị quan hệ để nhà phân tích khám phá liên kết giữa tên miền, tài khoản, tổ chức và dấu vết số.', intro:['Tài liệu Maltego mô tả quy trình bắt đầu từ một thực thể đầu vào, truy vấn các nguồn dữ liệu phù hợp rồi hiển thị kết quả thành các nút và mối liên kết. Cách trình bày này giúp người phân tích lần theo giả thuyết điều tra thay vì đọc các danh sách rời rạc.', 'Danh mục có tài liệu về Maltego, tích hợp Social Links và các tình huống OSINT. Kết quả phụ thuộc nguồn dữ liệu, quyền truy cập, truy vấn được chọn và quy trình xác minh của người sử dụng.'],capabilities:[{title:'Khám phá quan hệ',text:'Mở rộng một thực thể thành các liên kết dữ liệu để tìm mối quan hệ cần kiểm tra.'},{title:'Kết hợp nguồn dữ liệu',text:'Các transform và tích hợp cho phép truy vấn nhiều nguồn theo phạm vi giấy phép và quyền truy cập được cấp.'},{title:'Phân tích trực quan',text:'Đồ thị giúp sắp xếp thực thể, thuộc tính và mối liên hệ trong một cuộc điều tra.'},{title:'Lưu vết quá trình phân tích',text:'Có thể tổ chức kết quả và ghi nhận nguồn để nhóm rà soát, trao đổi hoặc tiếp tục điều tra.'}],useCases:['Rà soát dấu vết số công khai phục vụ điều tra an ninh mạng.','Tìm liên kết giữa tên miền, hạ tầng, tài khoản hoặc tổ chức trong một vụ việc.','Hỗ trợ phân tích thông tin nguồn mở theo quy trình đã được đơn vị phê duyệt.'],questions:[['Nguồn dữ liệu','Nguồn nào được bật, giấy phép nào áp dụng và dữ liệu được cập nhật ra sao?'],['Cơ sở pháp lý','Phạm vi thu thập và xử lý dữ liệu cá nhân đã được phê duyệt chưa?'],['Độ tin cậy','Nhóm sẽ xác minh kết quả từ nguồn độc lập nào trước khi kết luận?'],['Lưu trữ','Đồ thị điều tra, tài khoản và dữ liệu truy vấn được lưu ở đâu, trong bao lâu?']],partners:['Maltego','Social Links'] },
  '06-sechard': { headline: 'Đưa kiểm tra cấu hình và vận hành bảo mật về một quy trình', summary: 'SecHard tập hợp các công cụ quản trị an toàn hệ thống như security hardening, quản lý truy cập đặc quyền, tài sản, lỗ hổng và giám sát để hỗ trợ đội ngũ duy trì cấu hình bảo mật.', intro:['Tài liệu SecHard mô tả nền tảng quản trị bảo mật đa nhiệm, với các module cho hardening, PAM, quản lý tài sản, vulnerability management, device management, hiệu năng, TACACS, Syslog và quản lý rủi ro.', 'Giải pháp hướng đến việc kiểm tra trạng thái cấu hình, phát hiện điểm chưa phù hợp và theo dõi xử lý. Trước khi triển khai cần xác định hệ điều hành, thiết bị mạng, tài khoản quản trị và mức tự động hóa được phép.'],capabilities:[{title:'Đánh giá và tăng cường cấu hình',text:'Rà soát cấu hình theo chính sách, ghi nhận điểm cần xử lý và hỗ trợ theo dõi việc khắc phục.'},{title:'Quản lý tài khoản đặc quyền',text:'Tập trung quy trình truy cập quản trị; cần làm rõ cách cấp quyền, phê duyệt và lưu vết trong mô hình của đơn vị.'},{title:'Quản lý tài sản và lỗ hổng',text:'Tổng hợp thiết bị, tình trạng và phát hiện liên quan để hỗ trợ lập kế hoạch xử lý.'},{title:'Giám sát và ghi nhận',text:'Các tài liệu nhắc đến theo dõi hiệu năng, Syslog và TACACS; phạm vi tích hợp cần xác nhận theo hạ tầng thực tế.'}],useCases:['Rà soát hardening định kỳ cho máy chủ và thiết bị hạ tầng.','Chuẩn hóa quản lý tài khoản quản trị trên nhiều hệ thống.','Theo dõi trạng thái xử lý các phát hiện cấu hình trong vận hành.'],questions:[['Đối tượng quản lý','Danh sách hệ điều hành, thiết bị và phiên bản được hỗ trợ đã khớp với hạ tầng chưa?'],['Chính sách','Bộ baseline nào được dùng và ai chịu trách nhiệm phê duyệt ngoại lệ?'],['Quyền quản trị','Cần tích hợp LDAP/AD, MFA, quy trình phê duyệt hoặc lưu vết nào?'],['Tự động khắc phục','Những thay đổi nào được phép tự động áp dụng và cần cơ chế rollback nào?']],partners:['SecHard'] },
  '07-graylog': { headline: 'Tập trung log để nhóm vận hành nhìn rõ sự kiện', summary: 'Graylog thu thập, chuẩn hóa và tìm kiếm log tập trung. Bộ tài liệu nội bộ có cả nội dung SIEM/log management và một nhánh riêng về giám sát, bảo vệ API.', intro:['Với SIEM và quản lý log, giá trị thực tế phụ thuộc vào nguồn dữ liệu được kết nối, chất lượng parser, quy tắc cảnh báo và cách đội ngũ xử lý sự kiện. Graylog giúp đưa log từ nhiều thành phần về một nơi để tìm kiếm và xây dựng góc nhìn vận hành.', 'Thư mục còn có tài liệu Graylog API Security về khám phá API, phân loại rủi ro và quan sát request/response. Đây là phạm vi sản phẩm riêng, nên cần xác định rõ tổ chức đang tìm hiểu nền tảng log/SIEM hay nhánh API Security.'],capabilities:[{title:'Thu thập và chuẩn hóa log',text:'Kết nối nguồn log, định dạng dữ liệu để phục vụ tìm kiếm và phân tích tập trung.'},{title:'Tìm kiếm và cảnh báo',text:'Xây dựng truy vấn, dashboard và cảnh báo theo use case của nhóm SOC.'},{title:'Điều tra sự kiện',text:'Kết hợp dấu thời gian và dữ liệu từ nhiều nguồn để hỗ trợ rà soát chuỗi hoạt động.'},{title:'Nhánh API Security',text:'Tài liệu riêng mô tả khám phá API và quan sát hành vi; cần đánh giá riêng kiến trúc, dữ liệu và yêu cầu triển khai của module này.'}],useCases:['Tập trung log từ máy chủ, thiết bị mạng, ứng dụng và công cụ bảo mật.','Xây dựng quy trình phát hiện và điều tra sự kiện theo use case.','Đánh giá khả năng quan sát API nếu có nhu cầu với nhánh API Security.'],questions:[['Nguồn dữ liệu','Những nguồn log nào cần kết nối, lưu lượng mỗi ngày là bao nhiêu?'],['Lưu trữ','Thời gian lưu, yêu cầu phân vùng và chính sách dữ liệu nhạy cảm là gì?'],['Vận hành SOC','Ai theo dõi cảnh báo, xử lý escalations và tinh chỉnh rule?'],['Phạm vi sản phẩm','SIEM/log management hay API Security là ưu tiên của đợt đánh giá?']],partners:['Graylog'] },
  '08-keysight': { headline: 'Xây dựng môi trường lab và cyber range theo mục tiêu huấn luyện', summary: 'Tài liệu Keysight trong thư viện tập trung vào Cyber Range và nền tảng Cyber Security Operations Platform (CySOP), gồm thiết kế, cấu hình, triển khai và hướng dẫn vận hành.', intro:['Cyber Range tạo môi trường thực hành tách biệt để học viên hoặc đội ngũ kỹ thuật luyện tập trên kịch bản mạng và sự cố. Bộ tài liệu hiện có gồm đề xuất, kịch bản, hướng dẫn cài đặt và tài liệu sử dụng CySOP.', 'Một dự án cần bắt đầu từ số lượng người học, mô hình mạng, vai trò giảng viên, nội dung bài tập và cách khôi phục lab giữa các phiên. Cấu hình hạ tầng cần đối chiếu với tài liệu sizing và yêu cầu của đơn vị.'],capabilities:[{title:'Tổ chức môi trường thực hành',text:'Dựng hệ thống mạng và thành phần mô phỏng để người học làm việc trên tình huống có kiểm soát.'},{title:'Quản lý khóa học và kịch bản',text:'CySOP hỗ trợ vận hành môi trường; kịch bản cần được thiết kế theo cấp độ và mục tiêu huấn luyện.'},{title:'Triển khai và khai thác',text:'Thư viện có hướng dẫn cài đặt, deployment và sử dụng, thuận tiện cho đội kỹ thuật chuẩn bị môi trường.'},{title:'Đánh giá sau diễn tập',text:'Ghi nhận quá trình xử lý để giảng viên xem lại điểm mạnh, phần cần luyện thêm và mức phối hợp.'}],useCases:['Đào tạo SOC và diễn tập ứng cứu sự cố.','Tổ chức bài thực hành theo lớp, đội hoặc kịch bản chuyên môn.','Thử nghiệm công cụ và quy trình trong môi trường tách biệt.'],questions:[['Quy mô','Số người học đồng thời, số lớp và số kịch bản cần chạy là bao nhiêu?'],['Hạ tầng','Yêu cầu máy chủ, mạng, lưu trữ và phân vùng lab đã được khảo sát chưa?'],['Nội dung huấn luyện','Đội ngũ đã có kịch bản, dữ liệu mẫu và tiêu chí chấm điểm chưa?'],['Vận hành','Ai quản lý tài khoản, reset môi trường, cập nhật bài tập và hỗ trợ lớp học?']],partners:['Keysight'] },
  '09-exxact': { headline: 'Hạ tầng tính toán cho phòng lab, nghiên cứu và AI', summary: 'Exxact cung cấp các cấu hình máy chủ và hệ thống tính toán hiệu năng cao. Tài liệu trong thư viện gồm giới thiệu giải pháp và bảng khảo sát nhu cầu HPC.', intro:['Với hạ tầng HPC, cấu hình đúng bắt đầu từ workload: phần mềm cần chạy, dữ liệu, số người dùng, yêu cầu GPU/CPU, tốc độ lưu trữ và mạng kết nối. Tài liệu Exxact giúp đội ngũ hình thành cấu hình tham khảo và danh sách thông tin cần khảo sát.', 'Trang này giới thiệu Exxact ở góc độ hạ tầng. Hiệu năng thực tế cần được xác nhận bằng cấu hình cụ thể và phép thử phù hợp với workload của đơn vị; không nên suy ra chỉ từ tên dòng máy.'],capabilities:[{title:'Thiết kế cấu hình theo workload',text:'Lựa chọn CPU, GPU, bộ nhớ và lưu trữ dựa trên ứng dụng nghiên cứu hoặc mô hình AI cần chạy.'},{title:'Mở rộng hệ thống',text:'Xem xét số node, kết nối tốc độ cao, nguồn điện và khả năng mở rộng theo giai đoạn.'},{title:'Chuẩn bị môi trường lab',text:'Kết hợp máy chủ với nền tảng ảo hóa, phần mềm chuyên môn và quy trình quản lý người dùng.'},{title:'Khảo sát và nghiệm thu',text:'Dùng bảng câu hỏi HPC để làm rõ yêu cầu trước khi chốt cấu hình và tiêu chí đo hiệu năng.'}],useCases:['Phòng nghiên cứu AI/ML và phân tích dữ liệu.','Hạ tầng tính toán cho Cyber Range hoặc môi trường đào tạo.','Workload mô phỏng, dựng hình hoặc xử lý chuyên sâu.'],questions:[['Workload','Phần mềm, bộ dữ liệu và thời gian chạy mục tiêu là gì?'],['Tài nguyên','Cần GPU/CPU, bộ nhớ, dung lượng và thông lượng lưu trữ ra sao?'],['Mạng và điện','Yêu cầu kết nối node, làm mát, nguồn điện và không gian rack đã được khảo sát chưa?'],['Nghiệm thu','Bộ benchmark nào phản ánh đúng workload thực tế của đơn vị?']],partners:['Exxact'] },
  '10-accuknox': { headline: 'Bảo vệ workload cloud-native từ khâu phát triển đến runtime', summary: 'AccuKnox là nền tảng CNAPP theo hướng Zero Trust. Tài liệu trong thư viện giới thiệu bảo vệ workload, container và Kubernetes, từ quá trình build đến khi ứng dụng vận hành.', intro:['Khi ứng dụng được chia thành nhiều dịch vụ và chạy trên môi trường cloud-native, nhóm bảo mật cần hiểu workload nào đang tồn tại, quyền nào được cấp và hành vi nào diễn ra lúc chạy. Tài liệu AccuKnox tập trung vào khả năng nhìn xuyên suốt vòng đời này.', 'Các nội dung AI Security trong thư viện mở rộng chủ đề sang rủi ro của ứng dụng và tác nhân AI. Đây là nhánh cần được xác định theo kiến trúc, nền tảng triển khai và dữ liệu mà tổ chức sử dụng.'],capabilities:[{title:'Quan sát workload cloud-native',text:'Kiểm kê và theo dõi workload, container, Kubernetes cùng các thành phần liên quan trong môi trường được kết nối.'},{title:'Áp dụng nguyên tắc Zero Trust',text:'Rà soát danh tính, quyền và giao tiếp giữa workload để thu hẹp quyền truy cập không cần thiết.'},{title:'Bảo vệ build và runtime',text:'Kết hợp thông tin ở giai đoạn phát triển với hành vi khi chạy để phát hiện rủi ro theo vòng đời.'},{title:'Đánh giá AI Security',text:'Thư viện có tài liệu nền tảng về AI Security và AI Agent; phạm vi kiểm soát cần bám vào use case AI cụ thể.'}],useCases:['Bảo vệ cụm Kubernetes và ứng dụng cloud-native.','Rà soát quyền, cấu hình và hành vi workload.','Khảo sát rủi ro an ninh cho ứng dụng hoặc tác nhân AI.'],questions:[['Môi trường','Các cluster, cloud account, runtime và nền tảng CI/CD cần đưa vào phạm vi là gì?'],['Triển khai','Yêu cầu SaaS hay on-premise, quyền truy cập và luồng dữ liệu ra sao?'],['Chính sách','Những hành vi nào cần cảnh báo, chặn hoặc chỉ ghi nhận?'],['AI Security','Ứng dụng AI nào được đánh giá, dữ liệu nào đi qua và tiêu chí rủi ro là gì?']],partners:['AccuKnox'] },
  '11-penlink': { headline: 'Thu thập thông tin web theo phạm vi và quy trình điều tra', summary: 'Penlink Web Intelligence hỗ trợ thu thập và tra cứu thông tin trên web. Tài liệu thư viện gồm đề xuất kỹ thuật và thông số, là căn cứ để xác định nguồn dữ liệu, phạm vi sử dụng và yêu cầu triển khai.', intro:['Trong hoạt động điều tra, thông tin thường nằm rải rác trên nhiều dịch vụ và định dạng. Nền tảng Web Intelligence hướng đến việc hỗ trợ tìm kiếm, thu thập và tổ chức dữ liệu để nhà phân tích có thể xem xét trong một quy trình thống nhất.', 'Khả năng truy cập nguồn, độ mới của dữ liệu và điều kiện sử dụng phụ thuộc vào gói sản phẩm, giấy phép và quy định áp dụng. Cần xác minh các điểm này với tài liệu thông số và nhà cung cấp trước khi xây dựng quy trình.'],capabilities:[{title:'Tra cứu nhiều nguồn web',text:'Tổ chức hoạt động tìm kiếm theo đối tượng, chủ đề hoặc chỉ dấu đã được phê duyệt.'},{title:'Thu thập và sắp xếp kết quả',text:'Gom thông tin phục vụ rà soát, lưu hồ sơ và chuyển giao giữa các bước phân tích.'},{title:'Hỗ trợ điều tra',text:'Kết quả có thể làm đầu mối cho việc xác minh sâu hơn bằng các nguồn độc lập.'},{title:'Đánh giá theo thông số',text:'Tài liệu Penlink Specification là căn cứ để làm rõ nguồn, giới hạn, tích hợp và yêu cầu triển khai.'}],useCases:['Tra cứu nguồn web phục vụ công tác phân tích và điều tra.','Theo dõi chủ đề hoặc dấu hiệu đã xác định trong phạm vi được phép.','Chuẩn hóa quy trình thu thập và lưu trữ kết quả nghiên cứu.'],questions:[['Nguồn và quyền truy cập','Nguồn dữ liệu nào nằm trong phạm vi gói dịch vụ và điều kiện sử dụng?'],['Phạm vi điều tra','Đối tượng, thời hạn và cơ sở phê duyệt cho hoạt động thu thập là gì?'],['Lưu trữ dữ liệu','Kết quả được lưu ở đâu, thời hạn lưu và phân quyền truy cập ra sao?'],['Thông số kỹ thuật','Cần xác nhận tích hợp, triển khai, hiệu năng và hỗ trợ nào từ tài liệu specification?']],partners:['Penlink'] },
  '12-parasoft': { headline: 'Đưa kiểm thử chất lượng và bảo mật vào quy trình phát triển', summary: 'Parasoft cung cấp các công cụ phân tích và kiểm thử phần mềm. Tài liệu hiện có tập trung nhiều vào Test Data Management (TDM), cùng checklist khảo sát và nội dung kiểm thử.', intro:['Bộ tài liệu Parasoft trong thư viện hiện nghiêng về Test Data Management. TDM hỗ trợ chuẩn bị và quản lý dữ liệu kiểm thử để nhóm phát triển, QA và kiểm thử có thể tái tạo tình huống mà không phụ thuộc trực tiếp vào dữ liệu production.', 'Danh mục giải pháp còn gắn Parasoft với kiểm thử API, unit và phân tích mã trong quy trình DevSecOps. Cần xem đúng tài liệu theo module đang quan tâm, vì sản phẩm và yêu cầu triển khai có thể khác nhau.'],capabilities:[{title:'Quản lý dữ liệu kiểm thử',text:'Tạo, chuẩn bị và cung cấp bộ dữ liệu phù hợp cho các môi trường kiểm thử.'},{title:'Hỗ trợ kiểm thử phần mềm',text:'Tổ chức kiểm thử API, chức năng hoặc unit theo công cụ và module được triển khai.'},{title:'Tích hợp quy trình phát triển',text:'Làm rõ điểm tích hợp với CI/CD, công cụ quản lý mã và hệ thống theo dõi lỗi.'},{title:'Bảo vệ dữ liệu nhạy cảm',text:'Khi dùng dữ liệu gần production, cần xác nhận cơ chế masking, quyền truy cập và quản lý vòng đời dữ liệu.'}],useCases:['Giảm thời gian chuẩn bị dữ liệu cho QA và kiểm thử hồi quy.','Chuẩn hóa dữ liệu giữa các môi trường phát triển và kiểm thử.','Tích hợp kiểm tra chất lượng hoặc bảo mật vào pipeline phát triển.'],questions:[['Module','Đang đánh giá TDM, kiểm thử API, unit hay phân tích mã?'],['Nguồn dữ liệu','Dữ liệu lấy từ hệ thống nào và có yêu cầu masking hay ẩn danh không?'],['Tích hợp','Pipeline, công cụ quản lý mã và test framework nào cần kết nối?'],['Nghiệm thu','Cần đo thời gian cấp dữ liệu, độ bao phủ hay chất lượng kiểm thử?']],partners:['Parasoft'] },
  '13-cimcor': { headline: 'Theo dõi thay đổi để phát hiện sai lệch trên hệ thống', summary: 'Cimcor CimTrak tập trung vào giám sát tính toàn vẹn tệp và cấu hình. Khi thành phần quan trọng thay đổi, nhóm vận hành có thể nhận biết, đối chiếu và điều tra thay đổi đó.', intro:['Tài liệu Cimcor mô tả cơ chế theo dõi thay đổi trên máy chủ và thành phần hệ thống, đối chiếu với trạng thái tham chiếu để làm rõ thay đổi được phép hay cần điều tra. Đây là lớp kiểm soát bổ sung cho hoạt động quản lý cấu hình và ứng cứu sự cố.', 'Phạm vi giám sát, loại đối tượng và chính sách cảnh báo cần được thiết kế theo hệ điều hành, ứng dụng và yêu cầu tuân thủ của đơn vị.'],capabilities:[{title:'Giám sát tính toàn vẹn',text:'Theo dõi thay đổi của tệp, cấu hình và đối tượng được chọn theo chính sách.'},{title:'Đối chiếu trạng thái',text:'So sánh hiện trạng với baseline hoặc quy tắc để phát hiện sai lệch.'},{title:'Hỗ trợ điều tra',text:'Lưu thông tin thay đổi giúp xác định nội dung, thời điểm và hệ thống bị tác động.'},{title:'Quản lý tập trung',text:'Tài liệu đề cập repository quản lý dữ liệu giám sát; cần làm rõ kiến trúc, lưu trữ và dự phòng khi triển khai.'}],useCases:['Theo dõi thay đổi trái phép trên máy chủ quan trọng.','Hỗ trợ kiểm soát cấu hình và yêu cầu kiểm toán.','Điều tra thay đổi bất thường sau cảnh báo hoặc sự cố.'],questions:[['Đối tượng giám sát','Máy chủ, thư mục, registry và cấu hình nào cần theo dõi?'],['Baseline','Ai tạo và phê duyệt trạng thái chuẩn? Quy trình cập nhật baseline là gì?'],['Ngưỡng cảnh báo','Làm sao phân biệt thay đổi bảo trì hợp lệ với sai lệch đáng ngờ?'],['Tích hợp','Cảnh báo cần chuyển đến SIEM, ticketing hoặc quy trình nào?']],partners:['Cimcor'] },
  '14-iriusrisk': { headline: 'Nhận diện mối đe dọa ngay khi thiết kế hệ thống', summary: 'IriusRisk hỗ trợ threat modeling theo luồng dữ liệu: mô tả hệ thống đang xây dựng, xác định điều có thể xảy ra, chọn biện pháp xử lý và theo dõi việc khắc phục.', intro:['Tài liệu IriusRisk tổ chức hoạt động threat modeling thành bốn câu hỏi: hệ thống đang được xây dựng như thế nào, điều gì có thể sai, cần làm gì để giảm rủi ro và cách đánh giá mô hình đã đủ tốt chưa.', 'Đưa hoạt động này vào giai đoạn thiết kế giúp nhóm phát triển và bảo mật cùng nhìn vào kiến trúc, luồng dữ liệu, ranh giới tin cậy và quyết định kiểm soát trước khi phần mềm đi vào vận hành.'],capabilities:[{title:'Mô hình hóa kiến trúc',text:'Biểu diễn thành phần và luồng dữ liệu để xác định ranh giới tin cậy, tài sản và điểm giao tiếp.'},{title:'Nhận diện mối đe dọa',text:'Áp dụng phương pháp và thư viện quy tắc để tìm tình huống rủi ro theo thiết kế.'},{title:'Đưa ra biện pháp xử lý',text:'Liên kết phát hiện với khuyến nghị và công việc cần thực hiện trong quy trình phát triển.'},{title:'Theo dõi xuyên SDLC',text:'Quản lý mô hình và trạng thái xử lý để nhóm xem lại khi kiến trúc hoặc yêu cầu thay đổi.'}],useCases:['Threat modeling cho ứng dụng mới hoặc thay đổi kiến trúc lớn.','Chuẩn hóa đánh giá thiết kế giữa nhiều nhóm phát triển.','Kết nối phát hiện rủi ro với backlog và quy trình SDLC.'],questions:[['Phương pháp','Đơn vị đang dùng STRIDE, tiêu chuẩn nội bộ hay bộ quy tắc nào?'],['Quy trình','Ai tham gia tạo, duyệt và cập nhật threat model?'],['Tích hợp','Cần kết nối Git, Jira hoặc công cụ phát triển nào?'],['Phạm vi','Đánh giá SaaS hay on-premise, số nhóm và số mô hình ra sao?']],partners:['IriusRisk'] },
  '15-cyber-test': { headline: 'Huấn luyện đội ngũ trên kịch bản mạng có thể lặp lại', summary: 'Cyber Test System cung cấp môi trường cyber range phục vụ đào tạo và diễn tập. Thư viện có tài liệu kỹ thuật, kịch bản tấn công, yêu cầu quy mô 80 người dùng và ảnh giao diện sản phẩm.', intro:['Cyber range cho phép đội ngũ thực hành xử lý sự cố trên môi trường mô phỏng thay vì tác động vào hệ thống đang khai thác. Tài liệu Cyber Test System gồm danh mục kịch bản, thông số kỹ thuật, tài liệu giới thiệu và hướng dẫn giao diện.', 'Có thể dùng môi trường cho huấn luyện theo vai trò, diễn tập blue team và đánh giá khả năng phối hợp. Quy mô hạ tầng cần được tính theo số người dùng đồng thời, độ phức tạp của kịch bản và mức độ mô phỏng mong muốn.'],capabilities:[{title:'Dựng bài tập thực hành',text:'Sử dụng kịch bản và kho tình huống để tạo bài tập theo mục tiêu huấn luyện.'},{title:'Mô phỏng hoạt động tấn công',text:'Tài liệu có các chiến dịch và kịch bản nhiều cấp độ để phục vụ thực hành có kiểm soát.'},{title:'Hỗ trợ nhiều người dùng',text:'Bộ yêu cầu 80 người dùng giúp làm đầu vào khảo sát quy mô, nhưng cấu hình cuối cùng cần tính theo thiết kế được duyệt.'},{title:'Quan sát giao diện và thao tác',text:'Thư mục có ảnh chụp giao diện Cyber Test System bằng tiếng Việt để thành viên làm quen sản phẩm.'}],useCases:['Đào tạo nhóm blue team và nhân sự SOC.','Diễn tập theo kịch bản cho cơ quan, doanh nghiệp hoặc cơ sở đào tạo.','Đánh giá phối hợp con người, quy trình và công cụ trong tình huống mô phỏng.'],questions:[['Đối tượng học','Học viên có vai trò và trình độ nào, số lượng mỗi lớp bao nhiêu?'],['Kịch bản','Cần kịch bản có sẵn hay đội ngũ tự xây dựng theo tình huống nội bộ?'],['Hạ tầng','Yêu cầu người dùng đồng thời, máy trạm, mạng và cách cô lập lab là gì?'],['Đánh giá','Kết quả huấn luyện được chấm theo tiêu chí và báo cáo nào?']],partners:['Cyber Test System'] },
  '20-security-scorecard': { headline: 'Theo dõi mức độ phơi nhiễm an ninh nhìn từ bên ngoài', summary: 'Tài liệu SecurityScorecard giới thiệu security ratings để cung cấp góc nhìn về tình trạng an ninh bên ngoài của tổ chức và các bên liên quan trong chuỗi cung ứng.', intro:['Đánh giá bên ngoài có thể bổ sung góc nhìn cho hoạt động quản trị rủi ro: phát hiện tín hiệu cần rà soát, theo dõi thay đổi theo thời gian và hỗ trợ trao đổi với đơn vị phụ trách hoặc nhà cung cấp.', 'Thư viện hiện có tài liệu tổng quan và nội dung về rủi ro chuỗi cung ứng. Kết quả rating nên được xem là tín hiệu sàng lọc và cần xác minh bằng dữ liệu nội bộ, quy trình đánh giá và trao đổi với chủ thể liên quan.'],capabilities:[{title:'Góc nhìn bên ngoài',text:'Tổng hợp tín hiệu có thể quan sát từ Internet để hỗ trợ rà soát bề mặt hiện diện số.'},{title:'Theo dõi thay đổi',text:'So sánh biến động theo thời gian để xác định vấn đề cần ưu tiên xác minh.'},{title:'Hỗ trợ quản trị nhà cung cấp',text:'Dùng thông tin rating làm đầu vào cho quy trình rà soát rủi ro bên thứ ba.'},{title:'Phân loại và theo dõi xử lý',text:'Gắn phát hiện với chủ sở hữu, mức độ ưu tiên và hoạt động khắc phục nội bộ.'}],useCases:['Theo dõi tín hiệu rủi ro an ninh mạng của tổ chức.','Bổ sung thông tin trong chương trình đánh giá nhà cung cấp.','Xác định thay đổi cần đội ngũ xác minh trên tài sản thực tế.'],questions:[['Phạm vi tài sản','Tên miền, thương hiệu và pháp nhân nào thuộc phạm vi đánh giá?'],['Độ chính xác','Quy trình xử lý tài sản gán nhầm hoặc tín hiệu chưa chính xác ra sao?'],['Chuỗi cung ứng','Tiêu chí nào dùng để chọn nhà cung cấp cần theo dõi?'],['Hành động','Ai nhận cảnh báo, xác minh và đóng phát hiện?']],partners:['SecurityScorecard'] },
  '21-nowsecure': { headline: 'Kiểm thử bảo mật ứng dụng iOS và Android', summary: 'NowSecure tập trung vào kiểm thử bảo mật ứng dụng di động. Tài liệu mô tả hai phương án: nền tảng cloud và workstation triển khai tại chỗ cho hoạt động kiểm thử chuyên sâu.', intro:['Ứng dụng di động xử lý dữ liệu người dùng, xác thực và giao tiếp với API; kiểm thử cần xem xét cả mã ứng dụng lẫn hành vi khi chạy. Tài liệu NowSecure giới thiệu các kỹ thuật kiểm thử tĩnh, động và tương tác trên nền tảng iOS/Android.', 'NowSecure Platform hướng đến tự động hóa, còn Workstation phù hợp với quy trình phân tích tại chỗ. Thiết bị thật, loại ứng dụng, dữ liệu thử và nơi lưu kết quả là các điểm cần làm rõ trong giai đoạn đánh giá.'],capabilities:[{title:'Kiểm thử tự động ứng dụng',text:'Phân tích ứng dụng di động theo các phương pháp được tài liệu mô tả, nhằm tìm vấn đề bảo mật trong quá trình phát triển.'},{title:'Phân tích trên thiết bị thật',text:'Tài liệu nêu phương án thực hiện trên thiết bị iOS và Android thật thay vì chỉ phụ thuộc vào giả lập.'},{title:'Workstation tại chỗ',text:'Bộ kit on-premise hướng đến môi trường cần kiểm soát dữ liệu và thao tác phân tích nội bộ.'},{title:'Hỗ trợ khắc phục',text:'Kết quả kiểm thử giúp nhóm phát triển xem xét phát hiện và xác nhận lại sau khi cập nhật ứng dụng.'}],useCases:['Kiểm tra ứng dụng trước khi phát hành lên cửa hàng hoặc triển khai nội bộ.','Đánh giá ứng dụng mobile banking, dịch vụ công hoặc ứng dụng có dữ liệu nhạy cảm.','Thực hiện phân tích chuyên sâu trong môi trường không cho phép đưa mẫu lên cloud.'],questions:[['Ứng dụng','Cần đánh giá app iOS, Android, hybrid hay nhiều phiên bản?'],['Mô hình dữ liệu','Mẫu ứng dụng và dữ liệu kiểm thử được gửi lên nền tảng nào?'],['Triển khai','Cloud hay workstation phù hợp với chính sách dữ liệu của tổ chức?'],['Quy trình phát triển','Có cần kết nối CI/CD, kho mã hoặc quy trình phân loại lỗi không?']],partners:['NowSecure'] },
  '22-blancco': { headline: 'Xóa dữ liệu có kiểm soát trước khi tái sử dụng hoặc thanh lý thiết bị', summary: 'Blancco cung cấp phần mềm và thiết bị chuyên dụng để xóa dữ liệu trên máy tính, máy chủ, thiết bị di động, phương tiện lưu trữ và một số môi trường lưu trữ khác.', intro:['Tài liệu Blancco mô tả bài toán quản lý vòng đời tài sản: khi thiết bị được bàn giao, tái sử dụng hoặc thanh lý, tổ chức cần xử lý dữ liệu còn lưu trên đó và có bằng chứng cho quá trình thực hiện.', 'Danh mục sản phẩm trải từ công cụ xóa cho tệp, ổ đĩa, máy ảo và thiết bị di động đến thiết bị xử lý khối lượng lớn. Quy trình phải được chọn theo loại media, yêu cầu pháp lý, khả năng xác minh và chính sách lưu chứng nhận.'],capabilities:[{title:'Xóa dữ liệu theo loại thiết bị',text:'Chọn công cụ phù hợp cho máy trạm, ổ đĩa, thiết bị di động, máy ảo hoặc hệ thống lưu trữ.'},{title:'Quản lý tập trung',text:'Blancco Management Console hỗ trợ theo dõi hoạt động và trạng thái xử lý theo quy trình của tổ chức.'},{title:'Báo cáo và bằng chứng',text:'Ghi nhận kết quả xóa để phục vụ kiểm toán, bàn giao và quản lý vòng đời tài sản.'},{title:'Xử lý quy mô lớn',text:'Tài liệu có các phương án thiết bị xử lý nhiều ổ; cần tính theo loại ổ, tốc độ và sản lượng cần xử lý.'}],useCases:['Thanh lý hoặc tái sử dụng máy tính, máy chủ và ổ cứng.','Xử lý dữ liệu trên thiết bị di động hoặc phương tiện lưu trữ rời.','Chuẩn hóa bằng chứng xóa dữ liệu khi bàn giao tài sản.'],questions:[['Loại media','Đơn vị cần xử lý HDD, SSD, NVMe, thiết bị di động hay storage array?'],['Tiêu chuẩn','Quy định nội bộ và yêu cầu chứng nhận xóa dữ liệu nào đang áp dụng?'],['Khối lượng','Số thiết bị mỗi ngày, quy trình tại chỗ hay tập trung là gì?'],['Bằng chứng','Ai phê duyệt kết quả, lưu chứng nhận và đối soát tài sản?']],partners:['Blancco'] },
  '23-eggplant': { headline: 'Tự động hóa kiểm thử để nhìn sản phẩm từ góc độ người dùng', summary: 'Eggplant của Keysight tập trung vào kiểm thử chức năng, tự động hóa dựa trên mô hình và kiểm thử hiệu năng; tài liệu thư viện gồm Eggplant Functional, DAI Platform và Eggplant Performance.', intro:['Kiểm thử giao diện thường khó duy trì khi ứng dụng thay đổi liên tục. Eggplant kết hợp kiểm thử chức năng và tự động hóa theo mô hình để xây dựng kịch bản, thực thi trên nhiều nền tảng và rà soát hành trình sử dụng.', 'Eggplant Performance là nhánh dành cho kiểm thử hiệu năng. Mục tiêu, môi trường thử nghiệm và dữ liệu cần được xác định trước để kết quả có ý nghĩa với hệ thống thật.'],capabilities:[{title:'Kiểm thử chức năng',text:'Tạo và chạy kịch bản kiểm tra hành vi giao diện, luồng nghiệp vụ và trải nghiệm người dùng.'},{title:'Tự động hóa theo mô hình',text:'DAI hỗ trợ cách tiếp cận dựa trên mô hình và AI theo tài liệu sản phẩm; cần kiểm tra phạm vi ứng dụng phù hợp.'},{title:'Kiểm thử hiệu năng',text:'Eggplant Performance phục vụ các bài thử tải và đánh giá đáp ứng theo mục tiêu đã đặt.'},{title:'Đa nền tảng',text:'Xác định thiết bị, hệ điều hành, trình duyệt và môi trường cần kiểm thử để thiết kế bộ test phù hợp.'}],useCases:['Tự động hóa hồi quy cho ứng dụng có giao diện thay đổi thường xuyên.','Kiểm tra luồng nghiệp vụ xuyên nhiều màn hình hoặc thiết bị.','Đánh giá hiệu năng trước các đợt cao điểm hoặc phát hành lớn.'],questions:[['Phạm vi ứng dụng','Ứng dụng web, desktop, mobile và thiết bị nào cần được hỗ trợ?'],['Bộ kiểm thử','Nhóm đã có test case, dữ liệu và môi trường ổn định chưa?'],['Tích hợp','Cần kết nối pipeline, test management hay công cụ báo cáo nào?'],['Đo lường','Độ bao phủ, thời gian hồi quy và ngưỡng hiệu năng được đánh giá thế nào?']],partners:['Keysight Eggplant'] },
  '24-trend-micro': { headline: 'Bảo vệ máy chủ, endpoint và workload trên môi trường kết hợp', summary: 'Tài liệu Trend Micro trong thư viện gồm nội dung nền tảng và giải pháp tổng thể, xoay quanh bảo vệ endpoint, máy chủ và môi trường cloud.', intro:['Một tổ chức thường vận hành đồng thời máy trạm, máy chủ tại chỗ và workload cloud. Tài liệu Trend Micro giúp thành viên tra cứu cách phân lớp bảo vệ và phạm vi sản phẩm theo môi trường.', 'Danh mục có nhiều dòng sản phẩm và phiên bản, vì vậy cần đối chiếu đúng license, hệ điều hành, nền tảng cloud và kiến trúc hiện hữu trước khi xây dựng phương án. Trang này chỉ tóm tắt ở mức nhóm giải pháp, không thay cho cấu hình kỹ thuật cụ thể.'],capabilities:[{title:'Bảo vệ endpoint',text:'Rà soát nhu cầu bảo vệ máy trạm và máy chủ theo hệ điều hành, vị trí và cách quản trị.'},{title:'Bảo vệ workload cloud',text:'Xem xét các lớp kiểm soát cho workload cloud và mô hình vận hành kết hợp.'},{title:'Quản lý tập trung',text:'Xác định cách phân phối chính sách, nhận cảnh báo và cập nhật thành phần bảo vệ.'},{title:'Đánh giá nền tảng',text:'Tài liệu giải pháp tổng thể và platform là điểm bắt đầu để đối chiếu module, tích hợp và yêu cầu tài nguyên.'}],useCases:['Bổ sung lớp bảo vệ cho endpoint và máy chủ.','Rà soát bảo vệ workload trong môi trường cloud hoặc hybrid.','Chuẩn hóa quản lý chính sách và sự kiện từ nhiều nhóm tài sản.'],questions:[['Sản phẩm','Dòng sản phẩm và phiên bản nào nằm trong phạm vi cung cấp?'],['Môi trường','Hệ điều hành, hypervisor và nền tảng cloud nào cần hỗ trợ?'],['Tác động vận hành','Có yêu cầu loại trừ, hiệu năng hoặc thay đổi lịch cập nhật không?'],['Tích hợp','Sự kiện cần chuyển tới SIEM/XDR hoặc nền tảng nào?']],partners:['Trend Micro'] },
  '25-didomi': { headline: 'Quản lý lựa chọn quyền riêng tư xuyên suốt vòng đời consent', summary: 'Didomi giúp tổ chức xây dựng và vận hành quy trình quản lý sự đồng thuận: kiểm kê, cấu hình thông báo, triển khai, lưu bằng chứng, phân phối lựa chọn và phân tích.', intro:['Tài liệu Didomi mô tả vòng đời consent qua các bước Scan, Build, Deploy, Store, Distribute và Analyze. Cách tiếp cận này giúp các nhóm nhìn consent như một quy trình có quản trị thay vì chỉ là banner hiển thị trên website.', 'Thiết kế cần xét đến vùng pháp lý, kênh số, công nghệ quảng cáo/analytics, ngôn ngữ, nơi lưu hồ sơ và cách đồng bộ lựa chọn người dùng với hệ thống liên quan.'],capabilities:[{title:'Kiểm kê website và tracker',text:'Scan giúp rà soát cookie, nhà cung cấp và trạng thái các thành phần liên quan đến consent.'},{title:'Tạo và triển khai thông báo',text:'Build và Deploy hỗ trợ cấu hình trải nghiệm xin lựa chọn trên các kênh phù hợp.'},{title:'Lưu và phân phối lựa chọn',text:'Store và Distribute tập trung vào hồ sơ consent và việc truyền lựa chọn tới hệ thống cần thiết.'},{title:'Phân tích và quản trị',text:'Analyze giúp theo dõi thông tin consent; cần phân quyền và chính sách lưu trữ phù hợp.'}],useCases:['Quản lý consent cho website và ứng dụng số.','Chuẩn hóa banner và lựa chọn theo thị trường hoặc nhóm người dùng.','Lưu bằng chứng và đồng bộ lựa chọn với nền tảng marketing/analytics.'],questions:[['Phạm vi số','Website, ứng dụng và thương hiệu nào cần đưa vào kiểm kê?'],['Quy định','Những khu vực pháp lý và mục đích xử lý nào cần hỗ trợ?'],['Tích hợp','Các nền tảng analytics, CMP, CRM và quảng cáo cần nhận tín hiệu nào?'],['Lưu trữ','Hồ sơ consent được lưu, truy xuất và xóa theo chính sách nào?']],partners:['Didomi'] },
  '27-forcepoint': { headline: 'Giảm nguy cơ dữ liệu nhạy cảm rời khỏi tầm kiểm soát', summary: 'Forcepoint có tài liệu về danh mục bảo vệ dữ liệu, DLP và Data Security Posture Management. Các năng lực cần chọn theo nơi dữ liệu tồn tại, cách người dùng truy cập và chính sách của tổ chức.', intro:['Bảo vệ dữ liệu cần bắt đầu từ việc xác định dữ liệu quan trọng nằm ở đâu, ai có thể truy cập và cách dữ liệu được sử dụng hoặc chia sẻ. Tài liệu Forcepoint trong thư viện đề cập nhiều lớp bảo vệ, gồm DLP và DSPM.', 'Do danh mục sản phẩm rộng, trang này không gộp mọi module thành một tính năng duy nhất. Hãy mở đúng tài liệu giải pháp để đối chiếu môi trường endpoint, email, web, cloud và kho dữ liệu cần bảo vệ.'],capabilities:[{title:'Phát hiện dữ liệu cần bảo vệ',text:'Làm rõ loại dữ liệu, vị trí lưu trữ và kênh truyền trước khi xây dựng chính sách.'},{title:'Áp dụng chính sách DLP',text:'Thiết lập quy tắc kiểm soát theo dữ liệu, người dùng, kênh chia sẻ và hành động được phép.'},{title:'Đánh giá trạng thái dữ liệu',text:'Tài liệu DSPM giúp xem xét rủi ro liên quan đến dữ liệu trong môi trường được hỗ trợ.'},{title:'Theo dõi và tinh chỉnh',text:'Đánh giá cảnh báo, ngoại lệ và tác động người dùng để giảm rò rỉ mà không cản trở công việc hợp lệ.'}],useCases:['Kiểm soát dữ liệu nhạy cảm qua email, web, endpoint hoặc cloud theo module được chọn.','Tìm hiểu dữ liệu có rủi ro trong kho lưu trữ.','Chuẩn hóa chính sách xử lý và chia sẻ dữ liệu.'],questions:[['Phân loại','Đã có taxonomy dữ liệu và chủ sở hữu dữ liệu chưa?'],['Kênh kiểm soát','Endpoint, email, web, cloud hay repository nào cần nằm trong phạm vi?'],['Chính sách','Hành động nào cần chặn, cảnh báo, mã hóa hoặc cho phép ngoại lệ?'],['DSPM','Nguồn dữ liệu, connector, quyền truy cập và cách đánh giá rủi ro là gì?']],partners:['Forcepoint'] },
  '28-forestall': { headline: 'Tìm đường leo thang quyền trong môi trường danh tính', summary: 'Forestall tập trung vào Identity Security Posture Management, hỗ trợ đánh giá cấu hình và quan hệ danh tính trong Active Directory/Entra ID để nhận diện rủi ro và đường tấn công.', intro:['Tài liệu Forestall mô tả việc rà soát danh tính, quyền truy cập, group membership, delegation và trust relationship. Những quan hệ này có thể tạo đường leo thang đặc quyền nếu tài khoản hoặc cấu hình bị khai thác.', 'Giải pháp hướng đến giúp đội ngũ hiểu trạng thái danh tính và xác định việc cần ưu tiên: quyền dư thừa, tài khoản không còn sử dụng, cấu hình yếu hoặc quan hệ có thể dẫn tới tài sản quan trọng. Cần kiểm tra tương thích với cấu trúc thư mục và quy trình quản trị hiện có.'],capabilities:[{title:'Đánh giá trạng thái danh tính',text:'Rà soát đối tượng và cấu hình liên quan đến Active Directory hoặc Entra ID theo phạm vi được kết nối.'},{title:'Phân tích quan hệ và attack path',text:'Làm rõ group membership, delegation, trust và khả năng di chuyển ngang cần được xem xét.'},{title:'Ưu tiên xử lý quyền',text:'Hỗ trợ tìm quyền dư thừa hoặc cấu hình có rủi ro để chủ sở hữu danh tính rà soát.'},{title:'Theo dõi cải thiện',text:'Đối chiếu thay đổi trạng thái sau khi thu hồi quyền hoặc điều chỉnh cấu hình.'}],useCases:['Rà soát bảo mật Active Directory/Entra ID định kỳ.','Tìm đường leo thang đặc quyền và lateral movement.','Chuẩn bị kế hoạch làm sạch quyền và tài khoản dư thừa.'],questions:[['Phạm vi danh tính','Forest, domain, tenant và hệ thống danh tính nào được kết nối?'],['Quyền đọc/ghi','Giải pháp cần quyền nào; có thể bắt đầu ở chế độ chỉ đọc không?'],['Ưu tiên xử lý','Ai là chủ sở hữu quyết định thu hồi quyền hoặc thay đổi cấu hình?'],['Bằng chứng','Cần báo cáo và tiêu chí nào để xác nhận trạng thái đã cải thiện?']],partners:['Forestall'] },
  '29-simspace': { headline: 'Diễn tập an ninh mạng trên bản sao môi trường vận hành', summary: 'SimSpace Cyber Range cung cấp môi trường mô phỏng để huấn luyện đội ngũ, thực hành ứng phó và đánh giá phối hợp trên các kịch bản an ninh mạng.', intro:['Tài liệu SimSpace mô tả cyber range như môi trường mạng mô phỏng tách khỏi hệ thống sản xuất. Học viên có thể thực hành trên hạ tầng, ứng dụng và tình huống được dựng sẵn, sau đó cùng xem lại cách con người, công cụ và quy trình phối hợp.', 'Thư viện gồm tài liệu giới thiệu, catalog khóa học và attack catalog. Những tài liệu này hỗ trợ xây dựng lộ trình từ bài tập nền tảng đến diễn tập theo vai trò; cần chọn nội dung phù hợp với năng lực hiện tại của đội ngũ.'],capabilities:[{title:'Mô phỏng môi trường',text:'Tạo mạng thực hành với hệ thống và dịch vụ phục vụ mục tiêu huấn luyện.'},{title:'Tổ chức kịch bản',text:'Dùng catalog tình huống và lộ trình học để thiết kế bài diễn tập cho từng nhóm.'},{title:'Huấn luyện nhiều vai trò',text:'Thực hành phối hợp giữa SOC, ứng cứu sự cố, quản trị hệ thống và lãnh đạo theo kịch bản.'},{title:'Rút kinh nghiệm',text:'Đánh giá quyết định, thời gian phản ứng và điểm phối hợp để xây dựng kế hoạch cải thiện.'}],useCases:['Huấn luyện SOC, blue team và đội ứng cứu sự cố.','Diễn tập phối hợp liên phòng ban hoặc đánh giá readiness.','Xây dựng chương trình đào tạo theo cấp độ và lộ trình kỹ năng.'],questions:[['Mục tiêu đào tạo','Năng lực nào cần cải thiện và nhóm học viên gồm những ai?'],['Kịch bản','Dùng catalog có sẵn hay cần mô phỏng hạ tầng/quy trình riêng?'],['Quy mô vận hành','Số người dùng, vai trò và phiên diễn tập đồng thời là bao nhiêu?'],['Đánh giá','Ai chấm điểm, tiêu chí hoàn thành và báo cáo sau bài tập là gì?']],partners:['SimSpace'] },
  '666-fasoo': { headline: 'Bảo vệ tài liệu số xuyên suốt quá trình sử dụng', summary: 'Fasoo tập trung vào Enterprise DRM và bảo vệ dữ liệu ở cấp tài liệu. Nội dung trong thư viện giúp tìm hiểu cách kiểm soát quyền sử dụng, chia sẻ và vòng đời của tài liệu số.', intro:['Khác với chỉ kiểm soát nơi lưu file, DRM gắn chính sách bảo vệ với tài liệu để tổ chức quản lý cách mở, chỉnh sửa, in hoặc chia sẻ theo quyền được cấp. Tài liệu Fasoo giới thiệu Enterprise DRM và so sánh phương án với một số giải pháp cùng lĩnh vực.', 'Thiết kế chính sách cần tính đến thiết bị người dùng, ứng dụng văn phòng, cộng tác nội bộ/đối tác và quy trình khôi phục khi thay đổi nhân sự. Khả năng tương thích từng định dạng phải được xác nhận trong thử nghiệm.'],capabilities:[{title:'Áp chính sách vào tài liệu',text:'Gắn quyền truy cập và sử dụng với tài liệu theo người dùng hoặc nhóm được phép.'},{title:'Kiểm soát chia sẻ',text:'Quản lý hoạt động mở, chỉnh sửa và trao đổi tài liệu theo chính sách doanh nghiệp.'},{title:'Bảo vệ vòng đời dữ liệu',text:'Xem xét quyền tiếp tục áp dụng khi tài liệu được lưu, gửi hoặc di chuyển giữa môi trường.'},{title:'Quản trị tập trung',text:'Tài liệu Fasoo đề cập Enterprise DRM; cần xác nhận mô hình quản lý khóa, máy chủ và khả năng tích hợp.'}],useCases:['Bảo vệ tài liệu nội bộ và tài liệu chia sẻ với đối tác.','Kiểm soát quyền trên tài liệu nhạy cảm sau khi tải xuống.','Chuẩn hóa chính sách DRM cho người dùng và thiết bị.'],questions:[['Định dạng','Các định dạng văn phòng, CAD hoặc loại file chuyên ngành nào cần hỗ trợ?'],['Người dùng','Cần chia sẻ cho nhân viên, đối tác hay thiết bị không thuộc quản lý?'],['Chính sách','Quyền xem, sửa, in, copy và thời hạn truy cập được quy định thế nào?'],['Vận hành','Quy trình cấp lại quyền, thu hồi, khôi phục và xử lý offline ra sao?']],partners:['Fasoo'] },
  '96-seclab-tyrex': { headline: 'Kiểm soát luồng truy cập trong môi trường IT và OT', summary: 'Tài liệu Seclab tập trung vào cổng bảo mật mạng một chiều/hai chiều và kiểm soát truy cập từ xa; thư viện cũng có tài liệu Tyrex liên quan đến môi trường công nghiệp.', intro:['Mạng công nghiệp cần duy trì hoạt động ổn định trong khi vẫn kiểm soát kết nối với IT, đối tác và đội ngũ vận hành. Tài liệu Seclab SXN và Secure Remote Access là căn cứ để xem xét kiến trúc luồng, vùng mạng và điều kiện truy cập.', 'Thư mục còn có một số tài liệu về Tyrex và sản phẩm khác, vì vậy cần xác định đúng hãng, model và mục tiêu triển khai trước khi dùng tài liệu làm cơ sở thiết kế. Với OT, mọi thay đổi cần được đánh giá tác động vận hành và phê duyệt bởi chủ hệ thống.'],capabilities:[{title:'Kiểm soát luồng giữa các vùng',text:'Xem xét thiết kế cổng kết nối một chiều/hai chiều theo yêu cầu trao đổi dữ liệu và mô hình mạng.'},{title:'Truy cập từ xa có kiểm soát',text:'Tài liệu Secure Remote Access hỗ trợ thảo luận về kết nối quản trị từ xa và điểm cần bảo vệ.'},{title:'Phân vùng IT/OT',text:'Làm rõ nguồn, đích, giao thức và luồng dữ liệu được phép qua ranh giới mạng.'},{title:'Đánh giá yêu cầu kỹ thuật',text:'Đối chiếu thông số, băng thông, giao thức công nghiệp và điều kiện môi trường trước khi chọn thiết bị.'}],useCases:['Kiểm soát trao đổi dữ liệu giữa mạng IT và mạng OT.','Thiết kế kết nối từ xa cho nhà máy hoặc hệ thống hạ tầng.','Rà soát yêu cầu giám sát và bảo vệ các phân vùng công nghiệp.'],questions:[['Kiến trúc','Sơ đồ vùng mạng, luồng dữ liệu và điểm kết nối đã được chủ hệ thống xác nhận chưa?'],['Giao thức','Các giao thức công nghiệp và lưu lượng cần đi qua là gì?'],['Tính sẵn sàng','Thiết bị ảnh hưởng thế nào đến vận hành liên tục và phương án dự phòng?'],['Đúng sản phẩm','Tài liệu nào thuộc Seclab, Tyrex hoặc hãng khác trong thư mục cần được xác nhận?']],partners:['Seclab','Tyrex'] }
};

